//! Real-world vectors captured from OpenSSH 10.6p2 (the nix dev shell's `ssh`/`sshd`).
//!
//! Procedure (offline, no Trezor, no ~/.ssh): throwaway host and client keys made with
//! `ssh-keygen` in a temp directory; `sshd -D -e -f <temp config>` listening on
//! 127.0.0.1 with a temp `HostKey` and `AuthorizedKeysFile`; then
//! `ssh -F /dev/null -o UserKnownHostsFile=<temp> -o IdentityAgent=<socket> nobody@127.0.0.1`
//! against a tiny recording agent that offered the temp client key, answered SUCCESS to
//! extensions and FAILURE to the sign request. Each vector is a message body (without
//! the u32 length) exactly as `ssh` sent it. `host_fp` is what `ssh-keygen -lf` printed
//! for the temp host key. All keys were throwaway and have been deleted.
//!
//! Note: OpenSSH >= 8.9 talking to an OpenSSH >= 8.9 server signs the
//! `publickey-hostbound-v00@openssh.com` userauth variant, not plain `publickey`.

pub struct Capture {
    pub name: &'static str,
    pub host_fp: &'static str,
    pub session_bind: &'static str,
    pub sign_request: &'static str,
}

